head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/



//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = 'ULDMGT80220.gfm';
// 전역 변수 선언
scwin.isRun = true;
scwin.isAuto = true;
scwin.checkedAlarm;
scwin.firstDate;
scwin.lastDate;

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.MxDataSet_OnLoadCompleted = function(e) {
    textbox_1.setValue("총 " + rowcount + "건");
    scwin.checkData();
};

scwin.MxGrid_1_onheadcheckclick = function(headerId) {
    let check = 0;
    if (col === 0) {
        if (bCheck === 1) check = 1;
        // TODO Stage2: 0-based 검토
        for (let i = 1; i <= MxDataSet.getRowCount(); i++) {
            MxDataSet.setCellData(i, "CHK_FLAG", check);
        }
    }
};

scwin.btn_cal_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); //alert('image_2.onclick');

};

scwin.btn_sys_search_onclick = function(e) {
    if (txb_date.Text !== "") {

        //----W-Craft WebSquare 변환 확인: stop----//
        scwin.stopReload();
        scwin.isAuto = false;
        scwin.listSyncAuto();
    } else {
        alert("일자를 지정하십시요");
    }
};

scwin.btn_toExcel_onclick = function(e) {
    $c.data.downloadGridViewExcel(MxGrid_1, "코스닥매매시스템전문수신로그", "", "8");
};

scwin.btnStop_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: stop----//
    scwin.stopNotice();
};

scwin.button_1_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: stop----//
    scwin.stopReload();
};

// 일반 함수
 //true:자동refres, true:날짜 변경등으로 인한 수동 조회.
scwin.listSync = function() {
    scwin.isAuto = true;
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/kosdaqtrdlog.do",
        ref : "",
        target : "MxDataSet=body.content",
        submitDoneHandler : scwin.sbm_MxDataSet_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    scwin.setNowTime();
};

scwin.checkData = function() {
    if (scwin.setAlarmPlag()) scwin.checkAlarm();
};

scwin.checkAlarm = function() {
    let tmpChk;
    for (let i = 1; i <= MxDataSet.getRowCount(); i++) {
        tmpChk = MxDataSet.getCellData(i, "CHK_FLAG");

        //----W-Craft WebSquare 변환 확인: play----//

        //----W-Craft WebSquare 변환 확인: setTimeout----//
        if (tmpChk === 0) setTimeout('playNotice()', 1000);
    }
};

scwin.setAlarmPlag = function() {
    let idx = 0;
    if (scwin.checkedAlarm) {
        for (let i = 0; i < scwin.checkedAlarm.length; i++) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


            // TODO Stage2: 0-based 검토 (NameValueRow -> getMatchedIndex, 미발견 시 -1)
            idx = MxDataSet.getMatchedIndex("ROW_ID", scwin.checkedAlarm[i]);
            if (idx !== -1) MxDataSet.setCellData(idx, "CHK_FLAG", 1);
        }
    }
    return true;
};

//----W-Craft WebSquare 변환 확인: play----//
scwin.playNotice = function() {

    //----W-Craft WebSquare 변환 확인: play----//
    alertWave.play();
};

//----W-Craft WebSquare 변환 확인: stop----//
scwin.stopNotice = function() {
    scwin.isAuto = false;
    let tmpRowID;
    let tmpChkVal;
    let chkCnt = 0;
    scwin.checkedAlarm = new Array();
    if (MxDataSet.getRowCount() !== 0) {
        for (let i = 1; i <= MxDataSet.getRowCount(); i++) {
            tmpChkVal = MxDataSet.getCellData(i, "CHK_FLAG");
            if (tmpChkVal === 1) {
                scwin.checkedAlarm[chkCnt] = MxDataSet.getCellData(i, "ROW_ID");
                chkCnt++;
            }
        }
        if (chkCnt === 0) {
            alert('정지할 항목을 선택하세요.');
        } else {

            //----W-Craft WebSquare 변환 확인: stop----//
            alertWave.stop();

            //----W-Craft WebSquare 변환 확인: stop----//
            scwin.stopReload();
            scwin.listSyncAuto();
        }
    } else {
        alert('정지할 항목을 선택하세요.');
    }
};

scwin.setWave = function() {

    //----W-Craft WebSquare 변환 확인: play----//
    panelWav.style.display = 'none';
    panelWav.innerHTML = "<embed src='/sysmonitor/alert_elw.wav' name='alertWave' autostart='false' loop='true'>";
};

scwin.setNowTime = function() {
    let now = new Date();
    const hours = now.getHours();
    const mins = now.getMinutes();
    const secs = now.getSeconds();
    txtNowDate.setValue(hours + ":" + mins + ":" + secs);
};

scwin.getYYYYMMDD = function() {
    let now = new Date();
    let month = (now.getMonth() + 1) + "";
    let day = now.getDate() + "";
    if (day.length === 1) day = "0" + day;
    if (month.length === 1) month = "0" + month;
    return now.getYear() + "" + month + "" + day;
};

//ver:0 자동 ver:1 수동 조회버튼을 눌렀을경우 날짜를 갖고 넘어 가야함.
scwin.listSyncAuto = function() {

    //----W-Craft WebSquare 변환 확인: setInterval----//
    threadID = setInterval('reLoadData()', 60000);
    scwin.isRun = true;
    scwin.setAlertTxt();
    scwin.reLoadData();
};

scwin.reLoadData = function() {
    if (scwin.isAuto) txb_date.setValue(scwin.getYYYYMMDD());
    scwin.lastDate = txb_date.text;
    if (scwin.firstDate !== scwin.lastDate) {
        //날짜를 변경하면 선택한 리스트도 초기화 시켜준다.			
        scwin.checkedAlarm = new Array();
        scwin.firstDate = txb_date.text;

        //----W-Craft WebSquare 변환 확인: stop----//
        alertWave.stop();
    }
    if (scwin.isClearData()) scwin.listSync();
};

scwin.setAlertTxt = function() {
    if (scwin.isRun) txtAlert.setValue("1분 마다 reload 되고 있습니다.");

    else txtAlert.setValue("reload 중지되었습니다.");
};

scwin.isClearData = function() {
    if (txb_date.Text !== "") {
        MxDataSet.setJSON([]);
        return true;
    } else {
        alert("기준일자를 지정하십시요");
        return false;
    }
};

//----W-Craft WebSquare 변환 확인: stop----//
scwin.stopReload = function() {

    //----W-Craft WebSquare 변환 확인: clearInterval----//
    clearInterval(threadID);
    scwin.isRun = false;
    scwin.setAlertTxt();
};

scwin.MxGrid_1_CanColumnPosChange = function(row, colid) {
    return true;
};

scwin.gform_onload = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        submitDoneHandler : scwin.sbm_MxDataSet_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    $c.libRoundPanel.PanelToGroupBox_01(panel_1);

    //----W-Craft WebSquare 변환 확인: toDaySet----//
    toDaySet(txb_date); //firstDate를 셋팅하기 위해 첨에 한번하고  auto refresh될때 내일로 넘어갔는지 체크하기 위해  fn_list_sync_auto()에서 한번더 한다.
    scwin.firstDate = txb_date.text;
    scwin.setWave();
    scwin.listSyncAuto();
};
